function designRules() {
  function eventPhase(plan, now) {
    const start = Date.parse(plan.startAt), end = Date.parse(plan.endAt), time = Date.parse(now);
    if (![start, end, time].every(Number.isFinite) || start >= end) throw Error('invalid_event_window');
    if (!/T.*(?:Z|[+-]\d\d:\d\d)$/.test(plan.startAt) || !/T.*(?:Z|[+-]\d\d:\d\d)$/.test(plan.endAt)) throw Error('explicit_offset_required');
    return time < start ? 'before' : time < end ? 'during' : 'after';
  }
  function nextTransition({ plan, now, recordedPhase, approvedPlanVersion, currentOwnedContent, expectedOwnedContent, draftRevision, publishedRevision, pending }) {
    if (plan.paused) return { action: 'paused' };
    if (plan.version !== approvedPlanVersion) return { action: 'review_required', reason: 'plan_changed' };
    if (pending) return { action: 'reconcile', reason: 'pending_or_unknown_outcome' };
    if (draftRevision !== publishedRevision) return { action: 'review_required', reason: 'unpublished_draft' };
    if (JSON.stringify(currentOwnedContent) !== JSON.stringify(expectedOwnedContent)) return { action: 'review_required', reason: 'manual_edit' };
    const phase = eventPhase(plan, now);
    return phase === recordedPhase ? { action: 'no_change', phase } : { action: 'prepare', phase, key: `${plan.id}:${plan.version}:${phase}` };
  }
  function mergePage(existing, proposed, ownedId) {
    if (!Array.isArray(existing)) throw Error('invalid_pages');
    const current = existing.find(p => p.id === proposed.id);
    if (current && proposed.id !== ownedId) throw Error('unowned_page');
    if (existing.some(p => p.slug === proposed.slug && p.id !== ownedId)) throw Error('slug_collision');
    if (!current && existing.length >= 20) throw Error('page_limit');
    return current ? existing.map(p => p.id === ownedId ? proposed : p) : [...existing, proposed];
  }
  function campaign(brief) {
    if (!/^[a-z0-9][a-z0-9-]{0,47}$/.test(brief.id)) throw Error('invalid_campaign_id');
    if (!Number.isSafeInteger(brief.priceMinor) || brief.priceMinor < 0 || !/^[A-Z]{3}$/.test(brief.currency)) throw Error('invalid_price');
    if (!brief.title?.trim() || brief.title.length > 80 || !brief.audience?.trim()) throw Error('incomplete_brief');
    const deadline = Date.parse(brief.endsAt);
    if (!Number.isFinite(deadline) || !/T.*(?:Z|[+-]\d\d:\d\d)$/.test(brief.endsAt)) throw Error('invalid_deadline');
    const target = new URL(brief.ctaUrl), page = new URL(brief.pageUrl);
    if ([target, page].some(u => u.protocol !== 'https:' || u.username || u.password)) throw Error('https_required');
    const price = `${(brief.priceMinor / 100).toFixed(2)} ${brief.currency}`;
    const facts = { title: brief.title.trim(), price, endsAt: brief.endsAt, ctaUrl: target.href };
    const urls = {};
    for (const [channel, medium] of [['social', 'paid_social'], ['qr', 'offline']]) {
      const url = new URL(page);
      for (const [key, value] of Object.entries({ utm_source: channel, utm_medium: medium, utm_campaign: brief.id })) url.searchParams.set(key, value);
      urls[channel] = url.href;
    }
    return { facts, page: { title: facts.title, description: `${price} · ${facts.endsAt}`, ctaUrl: facts.ctaUrl }, ad: { headline: facts.title, body: `${price} · ${facts.endsAt}`, destination: urls.social }, urls, qrPayload: urls.qr };
  }
  function growth(report, minimum = 100) {
    if (report.configured !== true) return { state: 'not_configured', recommendation: null };
    if (![7, 30, 90].includes(report.periodDays)) throw Error('unexpected_period');
    const s = report.summary;
    if (!s || ![s.visits, s.clicks, report.comparison?.previous?.visits].every(n => Number.isFinite(n) && n >= 0)) throw Error('invalid_metrics');
    const observed = { periodDays: report.periodDays, visits: s.visits, clicks: s.clicks, clicksPer100Visits: s.visits ? Math.round(s.clicks / s.visits * 1000) / 10 : 0 };
    if (s.visits < minimum || report.comparison.previous.visits < minimum) return { state: 'insufficient_data', observed, recommendation: null };
    if (!report.detailed || !report.links?.length) return { state: 'summary_only', observed, recommendation: null };
    return { state: 'eligible_for_one_hypothesis', observed, recommendation: { kind: 'review_cta_clarity', hypothesis: 'Review one existing CTA against the most clicked destination.', causalClaim: false } };
  }
  return { eventPhase, nextTransition, mergePage, campaign, growth };
}
function exampleScenarios(kind) {
  const r = designRules(), outcomes = [];
  function check(name, test) {
    try { if (test() !== true) throw Error('assertion_failed'); outcomes.push({ scenario: name, passed: true }); }
    catch (error) { throw Error(`${name}: ${error.message}`); }
  }
  function throws(fn, message) { try { fn(); return false; } catch (e) { return e.message === message; } }
  const plan = { id: 'demo-workshop', version: 1, startAt: '2026-12-05T10:00:00+01:00', endAt: '2026-12-05T18:00:00+01:00', paused: false };
  const context = { plan, now: '2026-12-05T10:00:00+01:00', recordedPhase: 'before', approvedPlanVersion: 1, currentOwnedContent: ['approved-before'], expectedOwnedContent: ['approved-before'], draftRevision: 8, publishedRevision: 8, pending: false };
  const brief = { id: 'photo-workshop', title: 'Photography workshop', audience: 'Beginners', priceMinor: 4900, currency: 'EUR', endsAt: '2026-12-05T18:00:00+01:00', ctaUrl: 'https://example.com/book', pageUrl: 'https://example.com/demo/photo-workshop' };
  const report = { configured: true, detailed: true, periodDays: 7, summary: { visits: 250, clicks: 330 }, comparison: { previous: { visits: 200 } }, links: [{ label: 'portfolio', value: 100 }] };
  if (kind === 'event') {
    check('start boundary selects during', () => r.eventPhase(plan, context.now) === 'during');
    check('end boundary selects after', () => r.eventPhase(plan, plan.endAt) === 'after');
    check('downtime catches up directly to current phase', () => r.nextTransition({ ...context, now: '2026-12-06T10:00:00+01:00' }).phase === 'after');
    check('same phase does not repeat publication', () => r.nextTransition({ ...context, recordedPhase: 'during' }).action === 'no_change');
    check('changed plan requires approval', () => r.nextTransition({ ...context, approvedPlanVersion: 0 }).reason === 'plan_changed');
    check('foreign draft blocks publication', () => r.nextTransition({ ...context, draftRevision: 9 }).reason === 'unpublished_draft');
    check('manual change blocks transition', () => r.nextTransition({ ...context, currentOwnedContent: ['manual'] }).reason === 'manual_edit');
    check('unknown outcome requires reconciliation', () => r.nextTransition({ ...context, pending: true }).action === 'reconcile');
    check('pause preserves the public phase', () => r.nextTransition({ ...context, plan: { ...plan, paused: true } }).action === 'paused');
    check('winter and summer use explicit offsets', () => r.eventPhase({ ...plan, startAt: '2027-07-05T10:00:00+02:00', endAt: '2027-07-05T18:00:00+02:00' }, '2027-07-05T08:00:00Z') === 'during');
    check('missing offset is rejected', () => throws(() => r.eventPhase({ ...plan, startAt: '2026-12-05T10:00:00' }, context.now), 'explicit_offset_required'));
    check('invalid interval is rejected', () => throws(() => r.eventPhase({ ...plan, endAt: plan.startAt }, context.now), 'invalid_event_window'));
  } else if (kind === 'campaign') {
    const kit = r.campaign(brief);
    check('page and ad share exact price and deadline', () => kit.ad.body === kit.page.description);
    check('UTM query keeps existing values and escapes inputs', () => new URL(r.campaign({ ...brief, pageUrl: brief.pageUrl + '?ref=owner' }).urls.social).searchParams.get('ref') === 'owner');
    check('QR points to the same stable campaign destination', () => new URL(kit.qrPayload).pathname === new URL(brief.pageUrl).pathname);
    const other = { id: 'other', slug: 'other', links: [{ id: 'manual' }] }, proposed = { id: 'campaign-photo-workshop', slug: 'photo-workshop' };
    check('unmanaged pages are preserved exactly', () => r.mergePage([other], proposed, proposed.id)[0] === other);
    check('replay updates the same page without duplication', () => r.mergePage([other, proposed], { ...proposed, title: 'updated' }, proposed.id).length === 2);
    check('slug collision fails closed', () => throws(() => r.mergePage([{ id: 'foreign', slug: proposed.slug }], proposed, proposed.id), 'slug_collision'));
    check('negative price is rejected', () => throws(() => r.campaign({ ...brief, priceMinor: -1 }), 'invalid_price'));
    check('non HTTPS destination is rejected', () => throws(() => r.campaign({ ...brief, ctaUrl: 'http://example.com' }), 'https_required'));
    check('subpage cap is enforced', () => throws(() => r.mergePage(Array.from({ length: 20 }, (_, i) => ({ id: String(i), slug: `page-${i}` })), proposed, proposed.id), 'page_limit'));
    check('an unowned page cannot be adopted', () => throws(() => r.mergePage([proposed], proposed, 'someone-else'), 'unowned_page'));
  } else if (kind === 'growth') {
    check('missing analytics does not create a recommendation', () => r.growth({ configured: false }).state === 'not_configured');
    check('low current traffic returns insufficient evidence', () => r.growth({ ...report, summary: { visits: 20, clicks: 2 } }).recommendation === null);
    check('low previous traffic blocks comparison', () => r.growth({ ...report, comparison: { previous: { visits: 0 } } }).state === 'insufficient_data');
    check('basic plan produces summary only', () => r.growth({ ...report, detailed: false }).state === 'summary_only');
    check('no link attribution produces summary only', () => r.growth({ ...report, links: [] }).recommendation === null);
    check('sufficient data allows only one hypothesis', () => r.growth(report).recommendation.kind === 'review_cta_clarity');
    check('multiple clicks per visit may exceed 100', () => r.growth(report).observed.clicksPer100Visits === 132);
    check('hypothesis does not claim causality', () => r.growth(report).recommendation.causalClaim === false);
    check('invalid metrics stop analysis', () => throws(() => r.growth({ ...report, summary: { visits: -1, clicks: 0 } }), 'invalid_metrics'));
    check('actual supported period is required', () => throws(() => r.growth({ ...report, periodDays: 14 }), 'unexpected_period'));
  } else throw Error('unknown_design');
  return { design: kind, mode: 'SAMPLE', scenarios: outcomes.length, allPassed: true, externalCalls: 0, pageWrites: 0, emailsSent: 0, outcomes };
}
return [{json:exampleScenarios("growth")}];

function orbitRuntime() {
  const assert=(ok,message)=>{if(!ok)throw Error(message);};
  const stable=v=>JSON.stringify(sort(v));
  function sort(v){return Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v;}
  const equal=(a,b)=>stable(a)===stable(b);
  const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function text(v,max,label){assert(typeof v==='string'&&v.trim().length>0&&v===v.trim()&&v.length<=max,'Invalid '+label);return v;}
  function closed(v,keys){assert(v&&typeof v==='object'&&!Array.isArray(v),'Object required');assert(Object.keys(v).every(k=>keys.includes(k)),'Unsupported input field');return v;}
  function instant(v){assert(typeof v==='string'&&/^\d{4}-\d\d-\d\dT\d\d:\d\d(?::\d\d(?:\.\d{1,3})?)?(?:Z|[+-]\d\d:\d\d)$/.test(v)&&Number.isFinite(Date.parse(v)),'Explicit ISO timestamp and offset required');assert(new Date(v.slice(0,10)+'T00:00:00Z').toISOString().slice(0,10)===v.slice(0,10)&&Number(v.slice(11,13))<24,'Invalid calendar date or time');return v;}
  function https(v){text(v,2000,'HTTPS URL');assert(/^https:\/\/(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}(?::\d{1,5})?(?:[/?#][^\s<>"\\]*)?$/i.test(v),'Use an HTTPS URL without credentials');return v;}
  function slug(v){text(v,48,'slug');assert(/^[a-z0-9](?:[a-z0-9-]{0,46}[a-z0-9])?$/.test(v)&&!['admin','api','assets','cookies','dashboard','go','links','login','media','menu','privacy','shop','support','terms','www'].includes(v),'Invalid or reserved slug');return v;}
  function payload(v){return typeof v==='string'?JSON.parse(v):v;}
  function plan(raw){const p=closed(payload(raw),['id','version','slug','timezone','startAt','endAt','paused','before','during','after']);slug(p.id);slug(p.slug);assert(Number.isSafeInteger(p.version)&&p.version>0,'Positive plan version required');text(p.timezone,100,'timezone');try{new Intl.DateTimeFormat('en',{timeZone:p.timezone}).format();}catch{throw Error('Invalid IANA timezone');}instant(p.startAt);instant(p.endAt);assert(Date.parse(p.endAt)>Date.parse(p.startAt),'Event end must follow start');assert(p.paused===undefined||typeof p.paused==='boolean','paused must be boolean');for(const k of ['before','during','after']){const s=closed(p[k],['title','description','ctaLabel','ctaUrl']);text(s.title,80,k+' title');text(s.description,2000,k+' description');text(s.ctaLabel,200,k+' CTA');https(s.ctaUrl);}return p;}
  function brief(raw,now){const b=closed(payload(raw),['id','version','slug','title','audience','offer','priceMinor','currency','endsAt','termsUrl','ctaLabel','ctaUrl']);slug(b.id);slug(b.slug);assert(Number.isSafeInteger(b.version)&&b.version>0,'Positive campaign version required');for(const [k,max]of [['title',80],['audience',240],['offer',1000],['ctaLabel',200]])text(b[k],max,k);assert(Number.isSafeInteger(b.priceMinor)&&b.priceMinor>=0&&b.priceMinor<=100000000,'Invalid price');assert(['EUR','USD','GBP'].includes(b.currency),'Supported currencies: EUR, USD, GBP');instant(b.endsAt);assert(Date.parse(b.endsAt)>Date.parse(now),'Offer expired');https(b.termsUrl);https(b.ctaUrl);return b;}
  const phase=(p,now)=>Date.parse(now)<Date.parse(p.startAt)?'before':Date.parse(now)<Date.parse(p.endAt)?'during':'after';
  function body(r){assert(r&&r.statusCode>=200&&r.statusCode<300&&!r.error,'Provider read failed');return r.body;}
  function pub(r){const p=body(r).data;assert(p&&Number.isSafeInteger(p.draftRevision)&&Number.isSafeInteger(p.publishedRevision),'Invalid publication response');https(p.publicUrl);return p;}
  function pages(r){const p=body(r).data;assert(Array.isArray(p),'Invalid subpage collection');return p;}
  function draft(r){const p=body(r).data;assert(p&&Array.isArray(p.links)&&Array.isArray(p.subpages),'Invalid draft response');return p;}
  function revision(r){const tag=r.headers?.etag;assert(typeof tag==='string'&&tag.length>0,'Missing resource ETag');return tag;}
  function sameRevision(...rs){const revs=rs.map(r=>revision(r));assert(new Set(revs).size===1,'Workspace changed between reads; run again');return revs[0];}
  function rootContent(d){const x={...d};delete x.revision;delete x.updatedAt;delete x.subpages;return x;}
  function cleanBaseline(publication,draftRead,pagesRead){const p=pub(publication),d=draft(draftRead),ps=pages(pagesRead);sameRevision(publication,draftRead,pagesRead);assert(p.draftRevision===p.publishedRevision&&p.publicationStatus==='published','Unpublished or pending workspace changes; review them first');assert(equal(ps,d.subpages),'Inconsistent draft and subpage reads');return {publication:p,draft:d,pages:ps,etag:revision(publication),publicUrl:p.publicUrl.replace(/\/$/,'')};}
  function control(items){const rows=items.filter(r=>r&&r.id&&r.key==='control');assert(rows.length===1,'Initialize exactly one control row in the journal');const r=rows[0];assert(['idle','pending','review'].includes(r.state),'Invalid journal state');const state=JSON.parse(r.snapshot);assert(state&&state.runs&&typeof state.runs==='object','Invalid journal snapshot');return {...r,data:state};}
  function record(row,state,data,execution,now){return {key:'control',state,context:row.context,execution_id:String(execution),snapshot:JSON.stringify(data),updated_at:now};}
  function claim(row,expected,execution){assert(row&&row.execution_id===String(execution)&&['key','state','context','execution_id','snapshot','updated_at'].every(k=>row[k]===expected[k]),'Journal claim was lost or changed; execution stopped');return row;}
  function page(id,slugValue,title,description,blocks,now,createdAt){return {id,slug:slugValue,title,description:description.slice(0,240).trim(),links:blocks,enabled:true,createdAt:createdAt||now,updatedAt:now};}
  const block=(id,type,title,description='',url='')=>({id,type,title,description,url,isActive:true,...(type==='text'?{content:escape(description||title)}:{})});
  function eventPage(p,which,now,createdAt){const s=p[which],id='event-'+p.id;return page(id,p.slug,s.title,s.description,[block(id+'-heading','heading',s.title),block(id+'-body','text','Event details',s.description),block(id+'-cta','link',s.ctaLabel,'',s.ctaUrl)],now,createdAt);}
  function campaignPage(b,now,createdAt){const id='campaign-'+b.id,price=(b.priceMinor/100).toFixed(2)+' '+b.currency,facts=price+' · '+b.endsAt;return page(id,b.slug,b.title,b.offer,[block(id+'-heading','heading',b.title),block(id+'-offer','text','Offer details',b.offer),block(id+'-facts','text',facts),block(id+'-cta','link',b.ctaLabel,'',b.ctaUrl),block(id+'-terms','link','Terms and conditions','',b.termsUrl)],now,createdAt);}
  function pageContent(p){if(!p)return p;const x={...p};delete x.updatedAt;return x;}
  function merge(existing,proposed,owned){const current=existing.find(p=>p.id===proposed.id);assert(!current||owned&&equal(pageContent(current),pageContent(owned)),'Existing page is unowned or manually changed');assert(!existing.some(p=>p.slug===proposed.slug&&p.id!==proposed.id),'Subpage slug collision');assert(current||existing.length<20,'Subpage limit reached');return current?existing.map(p=>p.id===proposed.id?proposed:p):[...existing,proposed];}
  function checkPage(actual,expected){assert(actual&&actual.id===expected.id,'Expected subpage missing');for(const key of ['id','slug','title','description','enabled'])assert(actual[key]===expected[key],'Unexpected subpage '+key);assert(actual.links.length===expected.links.length,'Unexpected block count');expected.links.forEach((b,i)=>{for(const key of Object.keys(b))assert(equal(actual.links[i][key],b[key]),'Unexpected block '+key);});}
  function verifyDraft(baseline,current,intended){assert(equal(rootContent(current),rootContent(baseline.draft)),'Unrelated workspace content changed');assert(current.subpages.length===intended.pages.length,'Unexpected subpage count');for(const p of intended.pages){const actual=current.subpages.find(x=>x.id===p.id);if(p.id===intended.page.id)checkPage(actual,p);else assert(equal(pageContent(actual),pageContent(p)),'Unrelated subpage changed');}return current.subpages.find(p=>p.id===intended.page.id);}
  function utm(url,source,medium,campaign){https(url);const hashAt=url.indexOf('#'),hash=hashAt<0?'':url.slice(hashAt),base=hashAt<0?url:url.slice(0,hashAt),q=base.indexOf('?'),path=q<0?base:base.slice(0,q);const params=q<0?[]:base.slice(q+1).split('&').filter(Boolean);const keep=params.filter(s=>!['utm_source','utm_medium','utm_campaign'].includes(decodeURIComponent(s.split('=')[0])));for(const [k,v]of Object.entries({utm_source:source,utm_medium:medium,utm_campaign:campaign}))keep.push(k+'='+encodeURIComponent(v));return path+'?'+keep.join('&')+hash;}
  function kit(b,publicUrl,now,owned){const proposed=campaignPage(b,now,owned?.createdAt),url=https(publicUrl.replace(/\/$/,'')+'/'+b.slug);const facts=(b.priceMinor/100).toFixed(2)+' '+b.currency+' · '+b.endsAt;return {page:proposed,publicUrl:url,facts,ad:{headline:b.title,body:b.offer+' · '+facts,destination:utm(url,'social','paid_social',b.id)},caption:b.title+' — '+b.offer+' · '+facts,qrPayload:utm(url,'qr','offline',b.id)};}
  function approval(r,expiresAt,now){return r?.data?.approved===true&&Number.isFinite(Date.parse(expiresAt))&&Date.parse(now)<Date.parse(expiresAt);}
  function smtpReceipt(receipt){assert(Array.isArray(receipt.accepted)&&receipt.accepted.length===1&&Array.isArray(receipt.rejected)&&receipt.rejected.length===0&&typeof receipt.messageId==='string'&&/^250(?:[ -]|$)/.test(receipt.response),'SMTP acceptance was not verified; reconcile before resending');return receipt.messageId;}
  function publicSnapshot(html,intendedRevision){assert(typeof html==='string','Public HTML response missing');const m=html.match(/data-orbitpage-revision="(\d+)"/);assert(m&&Number(m[1])===intendedRevision,'Public revision not visible yet');const s=html.match(/window\.__ORBITPAGE_STATIC_SNAPSHOT__(?:\?\?=|=)([\s\S]*?);<\/script>/);assert(s,'Public page snapshot missing');const p=JSON.parse(s[1]).page;assert(p&&Array.isArray(p.links),'Invalid public snapshot');return p;}
  function verifyPublic(html,proposed,intendedRevision){const p=publicSnapshot(html,intendedRevision);checkPage({...proposed,links:p.links},proposed);return true;}
  function evidence(raw,minimum){const r=body(raw);assert(Number.isSafeInteger(minimum)&&minimum>=100,'Evidence floor must be at least 100');if(r.configured!==true)return {state:'not_configured',eligible:false,report:r};assert([7,30,90].includes(r.periodDays),'Unsupported actual analytics period');const nums=[r.summary?.visits,r.summary?.clicks,r.comparison?.previous?.visits,r.comparison?.previous?.clicks];assert(nums.every(n=>Number.isFinite(n)&&n>=0),'Invalid analytics metrics');const eligible=r.detailed===true&&r.summary.visits>=minimum&&r.comparison.previous.visits>=minimum&&Array.isArray(r.links)&&r.links.length>0;return {state:eligible?'needs_attribution':r.summary.visits<minimum||r.comparison.previous.visits<minimum?'insufficient_data':'summary_only',eligible,report:r};}
  function report(e,d,now){const a=e.report,previous=a.comparison?.previous;let target=null;if(e.eligible){const candidates=[];for(const link of a.links){const matches=d.links.filter(b=>b.isActive!==false&&['link','cta'].includes(b.type)&&[b.id,b.title,b.url].includes(link.label));if(matches.length===1)candidates.push({block:matches[0],clicks:link.value});}candidates.sort((x,y)=>y.clicks-x.clicks);if(candidates.length)target=candidates[0].block;}const lines=['OrbitPage analytics · '+now.slice(0,10),'Actual reporting window: '+(a.periodDays||'unavailable')+' days.'];if(a.configured===true){lines.push('Visits: '+a.summary.visits+'; clicks: '+a.summary.clicks+'.','Previous visits: '+previous.visits+'; previous clicks: '+previous.clicks+'.','Clicks per 100 visits: '+(a.summary.visits?Math.round(a.summary.clicks/a.summary.visits*1000)/10:0)+'. This is not a conversion rate.');}else lines.push('Analytics is not configured.');lines.push(target?'Hypothesis: review the clarity of one existing CTA: '+target.title+'. No causal or conversion claim.':'No edit recommendation: '+(e.eligible?'link attribution is ambiguous':e.state)+'.');return {text:lines.join('\n'),html:'<pre>'+escape(lines.join('\n'))+'</pre>',target,eligible:!!target,key:now.slice(0,10)+':'+(a.periodDays||0)};}
  function aiProposal(response,baseline,target,now){const b=body(response),p=b.proposal;assert(p&&typeof p.previewToken==='string'&&/^[A-Za-z0-9_-]{43}$/.test(p.previewToken),'AI did not return a usable preview');assert(p.expectedRevision===baseline.publication.draftRevision&&Date.parse(p.expiresAt)>Date.parse(now),'Stale or expired AI preview');const before=p.preview?.before,after=p.preview?.after;assert(before&&after&&equal(before.links,baseline.draft.links)&&equal(before.profile,baseline.draft.profile)&&equal(before.theme,baseline.draft.theme),'Preview baseline changed');assert(equal(before.profile,after.profile)&&equal(before.theme,after.theme)&&!after.shopProducts&&!after.menu,'AI changed unrelated sections');assert(after.links.length===before.links.length,'AI changed block count');let changed=0;after.links.forEach((b,i)=>{const old=before.links[i];if(old.id===target.id){text(b.title,200,'new CTA title');assert(b.title!==old.title,'AI returned no title improvement');assert(equal({...b,title:old.title},old),'AI changed more than the reviewed CTA title');changed++;}else assert(equal(b,old),'AI changed an unrelated block');});assert(changed===1,'Ambiguous AI target');return {...p,reviewHtml:'<h2>Publish this exact CTA title change?</h2><p>Revision '+p.expectedRevision+' · expires '+escape(p.expiresAt)+'</p><p>'+escape(target.title)+' → '+escape(after.links.find(b=>b.id===target.id).title)+'</p><p>Approve applies this preview and publishes the workspace.</p>'};}
  return {assert,stable,equal,escape,text,closed,instant,https,slug,payload,plan,brief,phase,body,pub,pages,draft,revision,sameRevision,rootContent,cleanBaseline,control,record,claim,page,block,eventPage,campaignPage,pageContent,merge,checkPage,verifyDraft,utm,kit,approval,smtpReceipt,publicSnapshot,verifyPublic,evidence,report,aiProposal};
